test('resolves only after slow writes have finished', async () => {
  const saved = new Map();
  const db = {
    async put(id, item) {
      await new Promise((r) => setTimeout(r, 20));
      saved.set(id, item);
    },
  };
  const n = await saveAll([{ id: 1 }, { id: 2 }, { id: 3 }], db);
  assert.strictEqual(n, 3);
  assert.strictEqual(saved.size, 3);
});

test('rejects when a write fails', async () => {
  const db = {
    async put(id) {
      if (id === 2) throw new Error('disk full');
    },
  };
  await assert.rejects(saveAll([{ id: 1 }, { id: 2 }], db), /disk full/);
});

